-- Qase PostgreSQL migration 039: recovery codes (#15725).
-- Single-use recovery codes generated by the account owner (Profile → Security)
-- after confirming their current password. Only the SHA-256 hex digest
-- (char(64)) of each code is stored; raw codes never touch the DB.
-- Regenerating replaces the whole set, so each row carries the generation
-- batch so prior rows can be invalidated atomically with one UPDATE.

CREATE TABLE qase_auth_recovery_codes (
	id uuid PRIMARY KEY,
	organization_id uuid NOT NULL,
	project_id uuid NOT NULL,
	user_id uuid NOT NULL,
	code_hash char(64) NOT NULL,
	generation int NOT NULL,
	created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
	used_at timestamptz,
	used_for text,
	CONSTRAINT qase_auth_recovery_codes_user_fk FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
	CONSTRAINT qase_auth_recovery_codes_project_fk FOREIGN KEY (organization_id, project_id) REFERENCES projects (organization_id, id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX qase_auth_recovery_codes_code_hash_key ON qase_auth_recovery_codes (code_hash);
CREATE INDEX qase_auth_recovery_codes_user_idx ON qase_auth_recovery_codes (user_id, generation, used_at);

ALTER TABLE qase_auth_recovery_codes ENABLE ROW LEVEL SECURITY;
ALTER TABLE qase_auth_recovery_codes FORCE ROW LEVEL SECURITY;
CREATE POLICY qase_auth_recovery_codes_tenant_scope ON qase_auth_recovery_codes FOR ALL
	USING (
		organization_id = NULLIF(current_setting('qase.organization_id', true), '')::uuid
		AND project_id = NULLIF(current_setting('qase.project_id', true), '')::uuid
	)
	WITH CHECK (
		organization_id = NULLIF(current_setting('qase.organization_id', true), '')::uuid
		AND project_id = NULLIF(current_setting('qase.project_id', true), '')::uuid
	);
